@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var css = step == CurrentStep ? "step active"
                : step < CurrentStep ? "step completed"
                : "step future";

        <div class="@css" @onclick="() => OnStepClick(step)">
            <div class="step-circle">
                @if (step < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[step]</div>
        </div>

        @if (step < StepNames.Count - 1)
        {
            <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigate { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Company" @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Title" @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => OnStartDateChange(e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" disabled="@IsCurrent" @onchange="e => OnEndDateChange(e.Value?.ToString())" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => OnCurrentChange((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public int Index { get; set; }
    [Parameter] public EventCallback<(int Index, string Field, object? Value)> OnFieldChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemoveEntry { get; set; }

    private async Task UpdateField(string field, string? value)
    {
        await OnFieldChanged.InvokeAsync((Index, field, value));
    }

    private async Task OnStartDateChange(string? value)
    {
        if (DateTime.TryParse(value, out var date))
            await OnFieldChanged.InvokeAsync((Index, nameof(StartDate), date));
    }

    private async Task OnEndDateChange(string? value)
    {
        if (DateTime.TryParse(value, out var date))
            await OnFieldChanged.InvokeAsync((Index, nameof(EndDate), (DateTime?)date));
    }

    private async Task OnCurrentChange(bool isCurrent)
    {
        await OnFieldChanged.InvokeAsync((Index, nameof(IsCurrent), isCurrent));
    }

    private async Task OnRemove()
    {
        await OnRemoveEntry.InvokeAsync(Index);
    }
}

