@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => OnChange(nameof(FullName), e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => OnChange(nameof(Email), e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => OnChange(nameof(Phone), e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => OnChange(nameof(Address), e.Value?.ToString())"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string Field, string? Value)> OnFieldChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    private async Task OnChange(string field, string? value)
    {
        await OnFieldChanged.InvokeAsync((field, value));
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        <div class="entry-card">
            <h4>Position @(i + 1)</h4>
            <WorkEntryForm
                Index="i"
                Company="@entry.Company"
                Title="@entry.Title"
                StartDate="@entry.StartDate"
                EndDate="@entry.EndDate"
                Description="@entry.Description"
                IsCurrent="@entry.IsCurrent"
                CanRemove="@(Entries.Count > 1)"
                OnFieldChanged="OnFieldChanged"
                OnRemoveEntry="OnRemoveEntry" />
        </div>
    }

    <button type="button" class="btn-secondary" @onclick="OnAdd">Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<(int Index, string Field, object? Value)> OnFieldChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemoveEntry { get; set; }
    [Parameter] public EventCallback OnAddEntry { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public string? ValidationError { get; set; }

    private async Task OnAdd() => await OnAddEntry.InvokeAsync();
    private async Task HandleNext() => await OnNext.InvokeAsync();

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
        public bool IsCurrent { get; set; }
    }
}

@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="hint">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
