@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" class="cover-letter-textarea" value="@CoverLetter"
            @onchange="e => OnChanged(e.Value?.ToString())"></textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public string? ValidationError { get; set; }

    private const int MaxLength = 2000;

    private async Task OnChanged(string? value)
    {
        await OnCoverLetterChanged.InvokeAsync(value ?? "");
    }

    private async Task HandleNext() => await OnNext.InvokeAsync();
}

@namespace sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply
@using static WorkHistoryStep
@using static ReferencesStep

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been submitted successfully.</p>
            <p class="application-id">Application ID: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <h2>Review & Submit</h2>

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email | @r.Phone
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="OnSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
}

arguments.file_text:
@page "/apply"
@using sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply
@using sv_ca41583e657649d2a4db788d72347aa6.Models
@using static WorkHistoryStep
@using static ReferencesStep
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigate="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                ValidationError="@validationError"
                IsValidating="@isValidating"
                OnFieldChanged="HandlePersonalFieldChanged"
                OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                ValidationError="@validationError"
                OnFieldChanged="HandleWorkFieldChanged"
                OnRemoveEntry="RemoveWorkEntry"
                OnAddEntry="AddWorkEntry"
                OnNext="HandleWorkNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                ValidationError="@validationError"
                OnFieldChanged="HandleReferenceFieldChanged"
                OnRemoveEntry="RemoveReference"
                OnAddEntry="AddReference"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                ValidationError="@validationError"
                OnCoverLetterChanged="HandleCoverLetterChanged"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                IsSubmitting="@isSubmitting"
                IsSubmitted="@isSubmitted"
                ApplicationId="@applicationId"
                ErrorMessage="@validationError"
                OnEdit="NavigateToStep"
                OnBack="GoBack"
                OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string? validationError;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    // Personal Info state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work History state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // References state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Cover Letter state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        validationError = null;
        currentStep = step;
    }

    private void GoBack()
    {
        validationError = null;
        currentStep--;
    }

    // Personal Info handlers
    private void HandlePersonalFieldChanged((string Field, string? Value) change)
    {
        validationError = null;
        switch (change.Field)
        {
            case "FullName": personalFullName = change.Value ?? ""; break;
            case "Email": personalEmail = change.Value ?? ""; break;
            case "Phone": personalPhone = change.Value ?? ""; break;
            case "Address": personalAddress = change.Value ?? ""; break;
        }
    }

    private async Task HandlePersonalNext()
    {
        if (string.IsNullOrWhiteSpace(personalFullName) ||
            string.IsNullOrWhiteSpace(personalEmail) ||
            string.IsNullOrWhiteSpace(personalPhone) ||
            string.IsNullOrWhiteSpace(personalAddress))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        validationError = null;
        StateHasChanged();

        var isValidEmail = await ApplicationService.ValidateEmailAsync(personalEmail);
        isValidating = false;

        if (!isValidEmail)
        {
            validationError = "Please enter a valid email address.";
            return;
        }

        currentStep = 1;
    }

    // Work History handlers
    private void HandleWorkFieldChanged((int Index, string Field, object? Value) change)
    {
        validationError = null;
        var entry = workEntries[change.Index];
        switch (change.Field)
        {
            case "Company": entry.Company = change.Value?.ToString() ?? ""; break;
            case "Title": entry.Title = change.Value?.ToString() ?? ""; break;
            case "StartDate": entry.StartDate = (DateTime)change.Value!; break;
            case "EndDate": entry.EndDate = (DateTime?)change.Value; break;
            case "Description": entry.Description = change.Value?.ToString() ?? ""; break;
            case "IsCurrent":
                entry.IsCurrent = (bool)change.Value!;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
        }
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void HandleWorkNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Company name and job title are required for all entries.";
                return;
            }
        }
        validationError = null;
        currentStep = 2;
    }

    // References handlers
    private void HandleReferenceFieldChanged((int Index, string Field, object? Value) change)
    {
        validationError = null;
        var reference = references[change.Index];
        switch (change.Field)
        {
            case "Name": reference.Name = change.Value?.ToString() ?? ""; break;
            case "Relationship": reference.Relationship = change.Value?.ToString() ?? ""; break;
            case "Email": reference.Email = change.Value?.ToString() ?? ""; break;
            case "Phone": reference.Phone = change.Value?.ToString() ?? ""; break;
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void HandleReferencesNext()
    {
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                validationError = "Name and email are required for all references.";
                return;
            }
        }
        validationError = null;
        currentStep = 3;
    }

    // Cover Letter handlers
    private void HandleCoverLetterChanged(string value)
    {
        validationError = null;
        coverLetter = value;
    }

    private void HandleCoverLetterNext()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationError = "Please write a cover letter.";
            return;
        }
        if (coverLetter.Length > 2000)
        {
            validationError = "Cover letter must be 2000 characters or fewer.";
            return;
        }
        validationError = null;
        currentStep = 4;
    }

    // Submit handler
    private async Task HandleSubmit()
    {
        isSubmitting = true;
        validationError = null;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(personalFullName, personalEmail, personalPhone, personalAddress);
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, refs, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            validationError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ccc;
    margin: 0 0.5rem;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #555;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    padding: 0.6rem 1.5rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
