@page "/apply"
@using sv_ca41583e657649d2a4db788d72347aa6.Components.Pages.Apply
@using sv_ca41583e657649d2a4db788d72347aa6.Models
@using static WorkHistoryStep
@using static ReferencesStep
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigate="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                ValidationError="@validationError"
                IsValidating="@isValidating"
                OnFieldChanged="HandlePersonalFieldChanged"
                OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                ValidationError="@validationError"
                OnFieldChanged="HandleWorkFieldChanged"
                OnRemoveEntry="RemoveWorkEntry"
                OnAddEntry="AddWorkEntry"
                OnNext="HandleWorkNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                ValidationError="@validationError"
                OnFieldChanged="HandleReferenceFieldChanged"
                OnRemoveEntry="RemoveReference"
                OnAddEntry="AddReference"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter"
                ValidationError="@validationError"
                OnCoverLetterChanged="HandleCoverLetterChanged"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                FullName="@personalFullName"
                Email="@personalEmail"
                Phone="@personalPhone"
                Address="@personalAddress"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                IsSubmitting="@isSubmitting"
                IsSubmitted="@isSubmitted"
                ApplicationId="@applicationId"
                ErrorMessage="@validationError"
                OnEdit="NavigateToStep"
                OnBack="GoBack"
                OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private string? validationError;
    private bool isValidating;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    // Personal Info state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Work History state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // References state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Cover Letter state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        validationError = null;
        currentStep = step;
    }

    private void GoBack()
    {
        validationError = null;
        currentStep--;
    }

    // Personal Info handlers
    private void HandlePersonalFieldChanged((string Field, string? Value) change)
    {
        validationError = null;
        switch (change.Field)
        {
            case "FullName": personalFullName = change.Value ?? ""; break;
            case "Email": personalEmail = change.Value ?? ""; break;
            case "Phone": personalPhone = change.Value ?? ""; break;
            case "Address": personalAddress = change.Value ?? ""; break;
        }
    }

    private async Task HandlePersonalNext()
    {
        if (string.IsNullOrWhiteSpace(personalFullName) ||
            string.IsNullOrWhiteSpace(personalEmail) ||
            string.IsNullOrWhiteSpace(personalPhone) ||
            string.IsNullOrWhiteSpace(personalAddress))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        validationError = null;
        StateHasChanged();

        var isValidEmail = await ApplicationService.ValidateEmailAsync(personalEmail);
        isValidating = false;

        if (!isValidEmail)
        {
            validationError = "Please enter a valid email address.";
            return;
        }

        currentStep = 1;
    }

    // Work History handlers
    private void HandleWorkFieldChanged((int Index, string Field, object? Value) change)
    {
        validationError = null;
        var entry = workEntries[change.Index];
        switch (change.Field)
        {
            case "Company": entry.Company = change.Value?.ToString() ?? ""; break;
            case "Title": entry.Title = change.Value?.ToString() ?? ""; break;
            case "StartDate": entry.StartDate = (DateTime)change.Value!; break;
            case "EndDate": entry.EndDate = (DateTime?)change.Value; break;
            case "Description": entry.Description = change.Value?.ToString() ?? ""; break;
            case "IsCurrent":
                entry.IsCurrent = (bool)change.Value!;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
        }
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void HandleWorkNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Company name and job title are required for all entries.";
                return;
            }
        }
        validationError = null;
        currentStep = 2;
    }

    // References handlers
    private void HandleReferenceFieldChanged((int Index, string Field, object? Value) change)
    {
        validationError = null;
        var reference = references[change.Index];
        switch (change.Field)
        {
            case "Name": reference.Name = change.Value?.ToString() ?? ""; break;
            case "Relationship": reference.Relationship = change.Value?.ToString() ?? ""; break;
            case "Email": reference.Email = change.Value?.ToString() ?? ""; break;
            case "Phone": reference.Phone = change.Value?.ToString() ?? ""; break;
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void HandleReferencesNext()
    {
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                validationError = "Name and email are required for all references.";
                return;
            }
        }
        validationError = null;
        currentStep = 3;
    }

    // Cover Letter handlers
    private void HandleCoverLetterChanged(string value)
    {
        validationError = null;
        coverLetter = value;
    }

    private void HandleCoverLetterNext()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationError = "Please write a cover letter.";
            return;
        }
        if (coverLetter.Length > 2000)
        {
            validationError = "Cover letter must be 2000 characters or fewer.";
            return;
        }
        validationError = null;
        currentStep = 4;
    }

    // Submit handler
    private async Task HandleSubmit()
    {
        isSubmitting = true;
        validationError = null;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(personalFullName, personalEmail, personalPhone, personalAddress);
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, refs, coverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            validationError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

